mapper.select:
SELECT a.id AS application_id, a.job_id, a.candidate_id, c.full_name AS candidate_name, a.status, a.applied_at, a.assigned_department_id, a.decided_by, a.decided_at, a.decision_comment FROM applications a JOIN candidates c ON c.id = a.candidate_id WHERE a.is_deleted = FALSE AND a.hm_approved = TRUE
AND a.job_id IN #{id}
ORDER BY a.decided_at DESC, a.id DESC
